from dataclasses import dataclass

@dataclass(frozen=True)
class Recipe:
    name: str
    cook: int
    verify: int

def speedup(r: Recipe) -> int:
    return max(r.cook - r.verify, 0)

def seq(r: Recipe, s: Recipe) -> Recipe:
    return Recipe(f'{r.name}+{s.name}', r.cook + s.cook, r.verify + s.verify)

def is_physical(r: Recipe) -> bool:
    return r.verify <= r.cook

menu = [Recipe('chicken', 90, 3), Recipe('stock', 300, 4),
        Recipe('bread', 1440, 2)]

for r in menu:
    for s in menu:
        assert is_physical(r) and is_physical(s)
        lhs, rhs = speedup(seq(r, s)), speedup(r) + speedup(s)
        assert lhs == rhs
        print(f'sp({r.name} then {s.name}) = {lhs} = {speedup(r)} + {speedup(s)}')
print('Speedup is additive over physical recipes.')

